          const checked = await api("/api/recovery/verify-mfa", { code });
          if (!checked.ok) { render(checked.message, "error"); return; }
          if (!pendingPassword) {
            state.step = 3;
            render("For safety, please choose your new password again after this refresh or pause.", "error"); return;
